window.__capBudgetedItemDamage=function(hc,damage){
  var plan=hc.__activeItemDamageBudget;
  if(!plan)return damage;
  var accepted=Math.min(Math.max(0,damage),Math.max(0,plan.remaining));
  if(!isFinite(accepted))accepted=0;
  plan.remaining=Math.max(0,plan.remaining-accepted);
  return accepted;
};
window.__budgetedItemHit=function(hc,damage,plan){
  if(!hc||hc.isDead||!hc.node||!hc.node.isValid||!(plan.remaining>0))return;
  var previous=hc.__activeItemDamageBudget;
  hc.__activeItemDamageBudget=plan;
  try{return hc.setDamage(damage);}finally{hc.__activeItemDamageBudget=previous;}
};
