// === 启动时 fetch 外部 JSON 覆盖（让 user 可独立编辑）===
(function(){
  try{
    var url="assets/passive_item_data.featherhpr1.json?t="+Date.now();
    fetch(url).then(function(r){return r.json();}).then(function(data){
      if(!data)return;
      // 覆盖 PASSIVES（保持原数组引用）
      if(data.passives&&data.passives.length){
        var byId={};
        PASSIVES.forEach(function(p){byId[p.id]=p;});
        data.passives.forEach(function(p){
          if(byId[p.id]){byId[p.id].name=p.name;byId[p.id].desc=p.desc;}
          else{PASSIVES.push({id:p.id,name:p.name,desc:p.desc});byId[p.id]=p;}
        });
        window.__PASSIVES=PASSIVES;
        console.log("[DATA] 加载了 "+data.passives.length+" 个被动定义");
      }
      // 覆盖 ITEM_DATA
      if(data.items&&data.items.length){
        window.__ITEM_DATA=data.items;
        console.log("[DATA] 加载了 "+data.items.length+" 个道具定义");
      }
    }).catch(function(e){console.log("[DATA] fetch err:",e&&e.message);});
  }catch(e){console.log("[DATA] init err:",e&&e.message);}
})();

