// GUIDE 按钮独立 setInterval：参考 soccer 按钮显示逻辑
(function(){
  function __getGCStable(){
    try{
      var gc=window.__require&&window.__require("ConfigManager");
      return gc&&gc.gameConfig?gc.gameConfig:null;
    }catch(e){return null;}
  }
  function __addGuideBtn(){
    if(document.getElementById("__guideBtnDom"))return;
    var gc=__getGCStable();if(!gc)return;
    if(gc.gameStart)return; // 战时不显示
    var dgb=document.createElement("button");
    dgb.id="__guideBtnDom";
    dgb.textContent="📖 GUIDE";
    dgb.style.cssText="position:fixed;top:20px;left:50%;transform:translateX(-50%);z-index:99999;padding:10px 28px;font-size:18px;font-weight:bold;color:#5d3a14;background:linear-gradient(180deg,#ffd54f,#ffa726);border:3px solid #5d3a14;border-radius:12px;cursor:pointer;box-shadow:0 4px 8px rgba(0,0,0,0.3);font-family:'JCRound',sans-serif;";
    dgb.onmouseover=function(){this.style.transform="translateX(-50%) scale(1.05)";};
    dgb.onmouseout=function(){this.style.transform="translateX(-50%) scale(1)";};
    dgb.onclick=function(){
      console.log("[GUIDE] DOM 按钮被点击");
      if(window.__openItemGuide)window.__openItemGuide();
    };
    document.body.appendChild(dgb);
  }
  // 周期性检查（参考 soccer 按钮）
  setInterval(function(){
    var gc=__getGCStable();
    var btn=document.getElementById("__guideBtnDom");
    if(gc&&gc.gameStart){
      // 战时：移除按钮
      if(btn)btn.remove();
    }else{
      // 主菜单：显示按钮
      if(!btn)__addGuideBtn();
    }
  },1000);
})();

/* 2. 选择面板 */
window.__openPassive=function(pNum){
  cc.assetManager.getBundle("prefabs").load("views/SkinsView",cc.Prefab,function(err,prefab){
    if(err||!prefab)return;
    var panel=cc.instantiate(prefab);
    panel.parent=cc.find("Canvas");panel.active=true;panel.zIndex=5;
    // 禁用 Widget（防止被自动重新居中）
    var w=panel.getComponent(cc.Widget);
    if(w){w.enabled=false;w.isAlignOnce=true;}
    // P1 贴屏幕左侧、P2 贴屏幕右侧（按屏幕大小算偏移）
    var sw=cc.winSize.width;
    panel.scale=1;
    // P1 贴左（锚点左中）；P2 贴右（默认锚点居中）
    if(pNum===1){
      panel.setAnchorPoint(0,0.5);
      panel.setPosition(-sw/2,0);
    }else{
      panel.setPosition(sw/2,0);
    }
    // 下一帧再设一次防 Widget 抢位
    panel.runAction(cc.callFunc(function(){
      var wd=panel.getComponent(cc.Widget);
      if(wd)wd.enabled=false;
      if(pNum===1){
        panel.setAnchorPoint(0,0.5);
        panel.setPosition(-sw/2,0);
      }else{
        panel.setPosition(sw/2,0);
      }
      panel.scale=1;
    }));
    // 禁用原始逻辑
    var sv=panel.getComponent("SkinsView");
    if(sv)sv.enabled=false;
    // 找 Content
    var contentNode=null;
    if(sv&&sv.Content){contentNode=sv.Content;}
    else{panel.getComponentsInChildren(cc.Node).forEach(function(n){if(n.name==="Content")contentNode=n;});}
    var itemTpl=sv?sv.ItemNode:null;
    if(contentNode){
      contentNode.destroyAllChildren();
      // 强制垂直布局
      var lay=contentNode.getComponent(cc.Layout);
      if(!lay)lay=contentNode.addComponent(cc.Layout);
      lay.type=cc.Layout.Type.VERTICAL;
      lay.resizeMode=cc.Layout.ResizeMode.CONTAINER;
      lay.spacingY=10;
      lay.paddingTop=20;
      lay.paddingBottom=20;
      var all=[{id:"random",name:"Random",desc:"Random each round"}].concat(PASSIVES);
      for(var i=0;i<all.length;i++){(function(p){
        // 不克隆 itemTpl 避免 SkinsItem 组件污染
        var item=new cc.Node(p.id);
        item.parent=contentNode;item.active=true;
        item.setContentSize(180,90);
        // 深底
        item.color=new cc.Color(45,55,75);
        var bgSp2=item.addComponent(cc.Sprite);
        bgSp2.sizeMode=cc.Sprite.SizeMode.CUSTOM;
        // weapon 风格黄色描边 + 内层柔光
        var border=new cc.Node("border");border.parent=item;
        border.setPosition(0,0);
        var bg=border.addComponent(cc.Graphics);
        // 外层金色描边
        bg.lineWidth=4;bg.strokeColor=new cc.Color(255,200,80);
        bg.fillColor=new cc.Color(60,75,100,200);
        bg.roundRect(-90,-45,180,90,10);
        bg.fill();bg.stroke();
        // 内层柔光
        bg.lineWidth=2;bg.strokeColor=new cc.Color(255,230,150,180);
        bg.roundRect(-86,-41,172,82,8);
        bg.stroke();
        // 名称（顶部）
        var n1=new cc.Node("n");n1.parent=item;n1.setPosition(0,18);
        var l1=n1.addComponent(cc.Label);l1.string=p.name;l1.fontSize=18;l1.lineHeight=22;
        n1.color=new cc.Color(255,230,140);
        n1.setContentSize(180,24);
        // 描述（底部，多行）
        var n2=new cc.Node("d");n2.parent=item;n2.setPosition(0,-15);
        n2.setContentSize(170,40);
        var l2=n2.addComponent(cc.Label);
        var descTxt=window.__zhWrap?window.__zhWrap(p.desc,10):p.desc;
        l2.string=descTxt;l2.fontSize=12;l2.lineHeight=14;
        n2.color=new cc.Color(220,225,240);
        l2.overflow=cc.Label.Overflow.NONE;l2.enableWrapText=true;
        // 点击：高亮 + 选中
        item.on(cc.Node.EventType.TOUCH_END,function(){
          var sel=p.id;
          if(pNum===1){window.__passives.p1=sel;window.__passivesOrig.p1=sel;}
          else{window.__passives.p2=sel;window.__passivesOrig.p2=sel;}
          var sn=PASSIVES.find(function(x){return x.id===sel;});
          console.log("[被动] P"+pNum+": "+(sn?sn.name:sel));
          panel.destroy();
        });
      })(all[i]);}
      // 修复 ScrollView 内容高度（让所有被动都能滚动看到）
      var totalH=all.length*85; // 每项70+间距15
      contentNode.setContentSize(contentNode.getContentSize().width,totalH);
      // 如果有 Layout 组件就用它，否则手动排列
      var layout=contentNode.getComponent(cc.Layout);
      if(layout){
        layout.type=cc.Layout.Type.GRID;
        layout.startAxis=cc.Layout.AxisDirection.HORIZONTAL;
        layout.cellSize=cc.size(180,90);
        layout.spacingX=10;
        layout.spacingY=10;
        layout.paddingTop=15;
        layout.paddingBottom=15;
        layout.resizeMode=cc.Layout.ResizeMode.CONTAINER;
        layout.updateLayout();
      }else{
        // 手动 2x N 网格排列
        for(var ci=0;ci<contentNode.children.length;ci++){
          var col=ci%2;var row=Math.floor(ci/2);
          contentNode.children[ci].setPosition(col===0?-95:95, totalH/2-35-row*80);
        }
      }
    }
    // 关闭
    panel.getComponentsInChildren(cc.Button).forEach(function(b){
      var nm=b.node.name.toLowerCase();
      if(nm.indexOf("close")!==-1||nm.indexOf("back")!==-1){
        b.clickEvents=[];b.node.on(cc.Node.EventType.TOUCH_START,function(){panel.destroy();});
        // P2 关闭按钮挪到左边（镜像 X 位置）
        if(pNum===2){
          var bp=b.node.getPosition();
          b.node.setPosition(-bp.x,bp.y);
        }
      }
    });
  });
};

/* 道具图鉴界面 — DOM 实现，仅用 SVG 图标 */
window.__openItemGuide=function(){};



(function(){
var shown="";var lastScene="";
setInterval(function(){
  var curScene=cc.director.getScene()?cc.director.getScene().name:"";
  if(curScene!==lastScene){lastScene=curScene;shown="";}
  var cn=cc.find("Canvas");if(!cn)return;
  var gm=cn.getComponent("Games");
  if(!gm||!gm.player||!gm.player.isValid)return;
  // 检测新回合（player 节点变化或 hp 重置为满）
  var hc1=gm.player.getComponent("HumanController");
  var hc2=gm.enemy?gm.enemy.getComponent("HumanController"):null;
  // round key: 用 player+enemy 节点的 uuid 标识本回合实例
  var roundKey=(gm.player.uuid||gm.player._id||"")+"|"+(gm.enemy?(gm.enemy.uuid||gm.enemy._id||""):"");
  if(window.__lastRoundKey!==roundKey){
    window.__lastRoundKey=roundKey;
    // 新回合：清空场上道具列表
    window.__fieldItems={};
    // === 全面清除上一回合遗留状态 ===
    if(window.__resetRoundState)window.__resetRoundState(gm,hc1,hc2);
    // 觉醒锁：我装的觉醒后永不再变
    var p1Locked=window.__sillyAwakenedP1;
    var p2Locked=window.__sillyAwakenedP2;
    // 新回合 - 刷新 random 选择（除非觉醒锁定）
    if(!p1Locked&&window.__passivesOrig.p1==="random"){window.__passives.p1=PASSIVES[Math.floor(Math.random()*PASSIVES.length)].id;console.log("[P] P1 random => "+window.__passives.p1);}
    if(!p2Locked&&window.__passivesOrig.p2==="random"){window.__passives.p2=PASSIVES[Math.floor(Math.random()*PASSIVES.length)].id;console.log("[P] P2 random => "+window.__passives.p2);}
    shown=""; // 强制重新显示
    // 重置一次性 flag
    if(gm.__pGCApplied)gm.__pGCApplied=false;
    // 新回合：我装的 20% 概率觉醒（如果选了我装的）
    if(window.__passives.p1==="silly"&&!p1Locked){
      if(Math.random()<0.20){window.__triggerSillyAwakening(gm,true);}
    }
    if(window.__passives.p2==="silly"&&!p2Locked){
      if(Math.random()<0.20){window.__triggerSillyAwakening(gm,false);}
    }
    // 已觉醒 - 持续应用觉醒状态
    if(p1Locked)window.__triggerSillyAwakening(gm,true,true);
    if(p2Locked)window.__triggerSillyAwakening(gm,false,true);
  }
  var key=(window.__passives.p1||"")+(window.__passives.p2||"");
  if(!key||key===shown){
    // 即使没变也要同步 label 可见性
    syncLblVisibility(gm);
    return;
  }
  shown=key;
  var p1p=PASSIVES.find(function(x){return x.id===window.__passives.p1;});
  var p2p=PASSIVES.find(function(x){return x.id===window.__passives.p2;});
  function addLabel(player,passive){
    if(!player||!passive)return;
    var centers=player.getChildByName("Centers");
    if(!centers)return;
    var old=centers.getChildByName("passiveLbl");
    if(old)old.destroy();
    var number=centers.getChildByName("number");
    var lbl=new cc.Node("passiveLbl");
    lbl.parent=centers;
    if(number)lbl.setPosition(number.x, number.y-35);
    else lbl.setPosition(0,-35);
    var lC=lbl.addComponent(cc.Label);
    lC.string=passive.name;
    lC.fontSize=16;
    lC.color=new cc.Color(255,220,100);
    lC.lineHeight=20;
  }
  addLabel(gm.player,p1p);
  if(gm.enemy&&gm.enemy.isValid)addLabel(gm.enemy,p2p);
  // 应用效果
  __applyP(gm);
  syncLblVisibility(gm);
},500);
// 同步 passiveLbl 跟 number 的 active 状态
function syncLblVisibility(gm){
  function sync(player){
    if(!player||!player.isValid)return;
    var centers=player.getChildByName("Centers");
    if(!centers)return;
    var lbl=centers.getChildByName("passiveLbl");
    if(lbl&&!lbl.active)lbl.active=true; // 永远显示被动名
  }
  sync(gm.player);
  if(gm.enemy)sync(gm.enemy);
}
})();

/* 4. 被动效果 */
function __applyP(gm){console.log('[PASSIVE] applying...',window.__passives.p1,window.__passives.p2);
  var h1=gm.player.getComponent("Human");
  var hc1=gm.player.getComponent("HumanController");
  if(!h1||!hc1)return;
  var hP=Object.getPrototypeOf(h1);
  var hcP=Object.getPrototypeOf(hc1);
  // 二段跳
  if(!hP.__pDJ){
    var oJ=hP.HumanJump;
    hP.HumanJump=function(){
      var isP1=this.node.name==="StickMan1";
      var has=(isP1&&window.__passives.p1==="doubleJump")||(!isP1&&window.__passives.p2==="doubleJump");
      // 地面：重置二段跳，走原始逻辑
      if(this._bodyState===0){
        this.__djD=false;
        return oJ.call(this);
      }
      // 空中 + 有被动：无限段跳（不再限制次数）
      if(has){
        if(!this.__djProg)this.__djProg=0;
        this.__djProg+=12;
        if(this.JumpLines){this.JumpLines.active=true;var bg=this.JumpLines.getChildByName("bg");if(bg)bg.width=Math.min(150,this.__djProg);}
        if(this.__djProg>=150){
          this.__djProg=0;
          if(this.JumpLines)this.JumpLines.active=false;
          var b=this.node.getChildByName("body");
          if(b){var rb=b.getComponent(cc.RigidBody);if(rb){
            rb.linearVelocity=cc.v2(rb.linearVelocity.x,0);
            rb.applyLinearImpulse(this.tempV2.mul(20),rb.getWorldCenter(),false);
          }}
        }
        return;
      }
      // 没有被动或已用过，走原始（空中时原始什么都不做）
      return oJ.call(this);
    };hP.__pDJ=true;
  }
  // 尖刺免疫+吸血
  if(!hcP.__pDmg){
    var oD=hcP.setDamage;
    hcP.setDamage=function(dmg){
      if(!this.node)return;
      var isP1=this.node.name==="StickMan1";
      // 尖刺免疫：地形尖刺/水域 setDamage(100)，攻击者为 null
      var hasSI=(isP1&&window.__passives.p1==="spikeImmune")||(!isP1&&window.__passives.p2==="spikeImmune");
      if(hasSI&&dmg>=50){console.log("[P] Spike immune blocked "+dmg);return;}
      // Glass Cannon: 攻击者伤害 +50%
      var aP1=!isP1;
      var atkGC=(aP1&&window.__passives.p1==="glassCannon")||(!aP1&&window.__passives.p2==="glassCannon");
      if(atkGC)dmg=Math.round(dmg*1.5);
      // Berserker: 攻击者血量越低伤害越高（最高 +100%）
      var atkBerserk=(aP1&&window.__passives.p1==="berserker")||(!aP1&&window.__passives.p2==="berserker");
      if(atkBerserk){try{var gB=cc.find("Canvas").getComponent("Games");
      var atkN=aP1?gB.player:gB.enemy;
      if(atkN&&atkN.isValid){var ahB=atkN.getComponent("HumanController");
      if(ahB){var ratio=ahB.hp/ahB.maxhp;dmg=Math.round(dmg*(2-ratio));}}}catch(e){}}
      // Stun Hit: 15% 概率眩晕
      var hasStun=(aP1&&window.__passives.p1==="stunHit")||(!aP1&&window.__passives.p2==="stunHit");
      if(hasStun&&Math.random()<0.15){
        try{var hN=this.node;var sBody=hN.getChildByName("body");
        if(sBody){var srb=sBody.getComponent(cc.RigidBody);
        if(srb){srb.linearVelocity=cc.v2(0,0);srb.angularVelocity=0;
        var oFix=srb.fixedRotation;srb.fixedRotation=true;
        setTimeout(function(){if(srb&&srb.node&&srb.node.isValid)srb.fixedRotation=oFix;},800);}}
        console.log("[P] Stun!");}catch(e){}
      }
      // Thorns: 受害者反弹 30% 伤害
      var hasThorns=(isP1&&window.__passives.p1==="thorns")||(!isP1&&window.__passives.p2==="thorns");
      if(hasThorns){
        try{var g3=cc.find("Canvas").getComponent("Games");
        var atk=aP1?g3.player:g3.enemy;
        if(atk&&atk.isValid){var ahc=atk.getComponent("HumanController");
        if(ahc&&!ahc.isDead){var refl=Math.ceil(dmg*0.5);
        var oDR=Object.getPrototypeOf(ahc).setDamage;
        oDR.call(ahc,refl);console.log("[P] Thorns reflect "+refl);}}}catch(e){}
      }
      var r=oD.call(this,dmg);
      // Lifesteal: 攻击者吸血
      if(dmg>0){
        var hasLS=(aP1&&window.__passives.p1==="lifesteal")||(!aP1&&window.__passives.p2==="lifesteal");
        if(hasLS){try{var g2=cc.find("Canvas").getComponent("Games");
        var a=aP1?g2.player:g2.enemy;if(a&&a.isValid){var ah=a.getComponent("HumanController");
        if(ah&&!ah.isDead)ah.hp=Math.min(ah.maxhp,ah.hp+Math.ceil(dmg*0.5));}}catch(e){}}
      }
      return r;
    };hcP.__pDmg=true;
  }
  // 弹射物
  function hR(joy,pN,grp){
    if(!joy)return;var jc=joy.getComponent("JoyStick");if(!jc)return;if(jc.__pR)return;
    var oA=jc.showattack;
    jc.showattack=function(){
      // Phoenix 无敌期间禁止攻击
      if(this.__phoenixLocked)return;
      oA.call(this);
      var isP1=pN.name==="StickMan1";
      var has=(isP1&&window.__passives.p1==="ricochet")||(!isP1&&window.__passives.p2==="ricochet");
      if(!has)return;
      try{var b=pN.getChildByName("body");if(!b)return;
      var pos=new cc.Vec2(0,0);b.getComponent(cc.RigidBody).getWorldPosition(pos);
      var ang=Math.random()*Math.PI*2;var dir=cc.v2(Math.cos(ang),Math.sin(ang));
      var cn2=cc.find("Canvas");var bf=null;
      cn2.getComponentsInChildren(cc.Component).forEach(function(c){if(c.getBullet&&c._pool)bf=c;});
      if(!bf)return;
      // 收集 bf._bullets 已有的弹丸键
      var keys=[];
      try{if(bf._bullets&&bf._bullets.forEach){bf._bullets.forEach(function(v,k){keys.push(k);});}}catch(e){}
      // 排除危险类型（炸弹会回伤队友）
      var safe=keys.filter(function(k){
        return k!=="bomb"&&k!=="bomb2"&&k!=="shareBoom"&&k!=="shareBoom2"&&k!=="dragon"&&k!=="potions";
      });
      var pool=safe.length?safe:keys;
      if(!pool.length)return;
      var pick=pool[Math.floor(Math.random()*pool.length)];
      // 武器 weaponConfig 需要 checkName，使用任意有此 bulletType 的武器
      var wpName=null;
      try{
        var modules=cc._RFpeek?null:null;
        // 查找 weaponConfig - 通过 BulletPool 自身记录
        if(bf._weaponConfig)wpName=null;
      }catch(e){}
      // 用 bf 直接克隆 prefab 创建 bullet
      var prefab=bf._bullets.get?bf._bullets.get(pick):null;
      if(!prefab)return;
      var bul=cc.instantiate(prefab);
      bul.parent=cc.find("Canvas/Bullets")||cc.find("Canvas");
      var rb=bul.getComponent(cc.RigidBody)||(bul.getChildByName("body")&&bul.getChildByName("body").getComponent(cc.RigidBody));
      if(rb){rb.setLinearVelocity(dir.mul(800));}
      var bb=bul.getComponent("BulletBase")||(bul.getChildByName("body")&&bul.getChildByName("body").getComponent("BulletBase"));
      if(bb){try{bb._init(grp,null,pN);bb.setVec(dir);}catch(e){console.log("[P] ricochet init err",e.message);}}
      bul.setPosition(pos.x,pos.y);
      console.log("[P] Ricochet "+pick);
      // 5 秒后销毁，防止屏幕堆积
      setTimeout(function(){if(bul&&bul.isValid)bul.destroy();},5000);
      }catch(e){console.log("[P] Ricochet err",e.message);}
    };jc.__pR=true;
  }
  hR(gm.playerJoy,gm.player,"weapons1");
  hR(gm.enemyJoy,gm.enemy,"weapons2");
  
  // Phoenix: hook _useBigSkill 阻止大招 + Triplecast 复读机
  function hUlt(joy){
    if(!joy)return;var jc=joy.getComponent("JoyStick");if(!jc)return;
    var jcP=Object.getPrototypeOf(jc);
    if(jcP.__pPhU)return;
    var oU=jcP._useBigSkill;
    jcP._useBigSkill=function(){
      if(this.__phoenixLocked){this.bigSkillTimer=0;return;}
      // 沉默道具：阻止大招
      try{
        var gmS=cc.find("Canvas").getComponent("Games");
        var isP1S=this.isPlayer1===1||this.isPlayer1===true;
        var pNS=isP1S?gmS.player:gmS.enemy;
        var hcS=pNS&&pNS.isValid?pNS.getComponent("HumanController"):null;
        if(hcS&&hcS.__silenced){this.bigSkillTimer=0;return;}
      }catch(_){}
      // 复读机：用 isPlayer1 字段判定持有者
      try{
        var gmU=cc.find("Canvas").getComponent("Games");
        // JoyStick.isPlayer1 = 1 是 P1，否则 P2
        var isP1=this.isPlayer1===1||this.isPlayer1===true;
        var pNode=isP1?gmU.player:gmU.enemy;
        var hcU=pNode&&pNode.isValid?pNode.getComponent("HumanController"):null;
        // trickster 这是啥啊：大招变成随机道具效果
        var passiveT=isP1?window.__passives.p1:window.__passives.p2;
        if(passiveT==="trickster"&&pNode&&pNode.isValid){
          var trickPool=[0,2,3,7,10,11,21,33,38,64,70,73,80,100,101,130,131,160];
          var pickT=trickPool[Math.floor(Math.random()*trickPool.length)];
          if(window.__applyItemToOne)window.__applyItemToOne(pickT,pNode);
          this.bigSkillTimer=0;
          console.log("[P] Trickster 大招变 state="+pickT);
          return;
        }
        // gravitywell 你过来啊：大招把对手拉向自己
        // 原实现只在大招调用前写一次 linearVelocity；随后原版大招/角色移动会覆盖它，
        // 且没有使用项目中已确认可用的 setLinearVelocity。改为原版调用返回后短时重施，
        // 每次按当前世界坐标重算方向，不改全局重力或其他被动。
        if(passiveT==="gravitywell"&&pNode&&pNode.isValid){
          try{
            var oppGW=isP1?gmU.enemy:gmU.player;
            if(oppGW&&oppGW.isValid){
              var meBd=pNode.getChildByName("body");
              var opBd=oppGW.getChildByName("body");
              var meRb=meBd&&meBd.getComponent(cc.RigidBody);
              var opRb=opBd&&opBd.getComponent(cc.RigidBody);
              if(meRb&&opRb){
                var pullGW=function(){
                  try{
                    if(!pNode.isValid||!oppGW.isValid)return;
                    var meP=cc.v2(0,0),opP=cc.v2(0,0);
                    meRb.getWorldPosition(meP);opRb.getWorldPosition(opP);
                    var dir=meP.sub(opP),dist=dir.mag();
                    if(dist>1){
                      dir=dir.normalize();
                      // 保留当前设计：越远拉得越猛；重复施加以抵抗移动控制覆盖
                      var force=Math.min(2500,dist*3);
                      var vel=cc.v2(dir.x*force,Math.abs(dir.y*force)+300);
                      if(typeof opRb.setLinearVelocity==="function")opRb.setLinearVelocity(vel);
                      else opRb.linearVelocity=vel;
                    }
                  }catch(_pullGW){}
                };
                // 原版 BigDamage 先执行，避免它覆盖引力结果
                for(var gwI=0;gwI<7;gwI++)setTimeout(pullGW,gwI*50);
                if(window.__toastNearPlayer)window.__toastNearPlayer("🌀 引力!",pNode,new cc.Color(180,120,255),26);
              }
            }
          }catch(eGW){}
          // 你过来啊仍然正常释放大招（不 return），所以继续往下走原版
        }
        if(hcU&&hcU.__triplecast&&hcU.__triplecast>0){
          var jcSelf=this;
          var n=hcU.__triplecast;
          hcU.__triplecast=0;
          // 立即放第一次
          oU.call(this);
          // 后续 n-1 次延迟
          for(var ti=1;ti<n;ti++){
            (function(delay){
              setTimeout(function(){
                if(!jcSelf||!jcSelf.node||!jcSelf.node.isValid)return;
                try{oU.call(jcSelf);}catch(e){console.log("[ITEM] echo err:",e&&e.message);}
              },delay);
            })(ti*400);
          }
          console.log("[ITEM] 复读机连放 "+n+" 次");
          return;
        }
      }catch(eU){console.log("[ITEM] echo outer err:",eU&&eU.message);}
      return oU.call(this);
    };
    jcP.__pPhU=true;
  }
  hUlt(gm.playerJoy);
  hUlt(gm.enemyJoy);
  
  // Glass Cannon: 每回合开局调整 HP（一次性）
  if(!gm.__pGCApplied){
    gm.__pGCApplied=true;
    if(window.__passives.p1==="glassCannon"&&hc1){
      var orig1=hc1.maxhp;
      hc1.maxhp=Math.round(hc1.maxhp*0.75);
      hc1.hp=hc1.maxhp;
      console.log("[P] Glass Cannon P1: maxhp "+orig1+" => "+hc1.maxhp);
      // 同步 HealthBar
      if(hc1.HealthBar){var pb1=hc1.HealthBar.getComponent(cc.ProgressBar);if(pb1)pb1.progress=1;}
    }
    var hc2_=gm.enemy.getComponent("HumanController");
    if(window.__passives.p2==="glassCannon"&&hc2_){
      var orig2=hc2_.maxhp;
      hc2_.maxhp=Math.round(hc2_.maxhp*0.75);
      hc2_.hp=hc2_.maxhp;
      console.log("[P] Glass Cannon P2: maxhp "+orig2+" => "+hc2_.maxhp);
      if(hc2_.HealthBar){var pb2=hc2_.HealthBar.getComponent(cc.ProgressBar);if(pb2)pb2.progress=1;}
    }
  }
  
  // Phoenix: 复活 + 5 秒无敌
  // 前置拦截：致死伤害直接吞掉 + 手动复活，绝不让原版死亡流程（结算页面）触发
  if(!hcP.__pPhoenix){
    var oDmgP=hcP.setDamage;
    hcP.setDamage=function(dmg){
      if(!this.node)return;
      var isP1=this.node.name==="StickMan1";
      var hasPhoenix=(isP1&&window.__passives.p1==="reviveOnce")||(!isP1&&window.__passives.p2==="reviveOnce");
      // 无敌期间任何伤害都吃掉
      if(this.__phoenixInvuln){return;}
      // 非致死 → 正常走原版
      return oDmgP.call(this,dmg);
    };
    hcP.__pPhoenix=true;
  }
  // Berserker: 在 setDamage hook 中处理（已经 hook，需要扩展）
  // 改用全局 interval 检查 hp 比例修改伤害
  
  // Aegis: 每2秒恢复1HP
  if(!gm.__pAegisI){
    gm.__pAegisI=setInterval(function(){
      if(!gm||!gm.player)return;
      function regen(p,isP1){
        if(!p||!p.isValid)return;
        var has=(isP1&&window.__passives.p1==="shieldRegen")||(!isP1&&window.__passives.p2==="shieldRegen");
        if(!has)return;
        var h=p.getComponent("HumanController");
        if(h&&!h.isDead&&h.hp<h.maxhp)h.hp=Math.min(h.maxhp,h.hp+5);
      }
      regen(gm.player,true);
      regen(gm.enemy,false);
    },1000);
  }
  
  // Magnet: 物品自动吸过来
  if(!gm.__pMagI){
    gm.__pMagI=setInterval(function(){
      if(!gm||!gm.player)return;
      function pull(p,isP1){
        if(!p||!p.isValid)return;
        var has=(isP1&&window.__passives.p1==="magnet")||(!isP1&&window.__passives.p2==="magnet");
        if(!has)return;
        var body=p.getChildByName("body");if(!body)return;
        var pos=new cc.Vec2(0,0);body.getComponent(cc.RigidBody).getWorldPosition(pos);
        // 全局搜索 BuffItem 节点（任何位置）
        var cn=cc.find("Canvas");if(!cn)return;
        var items=[];
        cn.getComponentsInChildren(cc.Component).forEach(function(c){
          if(c.constructor&&c.node&&c.node.isValid){
            var nm=c.node.name;
            if(nm&&nm.indexOf("BuffItem")===0&&items.indexOf(c.node)===-1)items.push(c.node);
          }
        });
        items.forEach(function(it){
          if(!it.isValid)return;
          var rb=it.getComponent(cc.RigidBody);
          if(!rb)return;
          var ipos=new cc.Vec2(0,0);rb.getWorldPosition(ipos);
          var dx=pos.x-ipos.x;var dy=pos.y-ipos.y;
          var dist=Math.sqrt(dx*dx+dy*dy);
          if(dist<500&&dist>30){
            var f=12000;
            rb.applyForceToCenter(cc.v2(dx/dist*f,dy/dist*f),true);
          }
        });
      }
      pull(gm.player,true);
      pull(gm.enemy,false);
    },50);
  }
// 血条变化检测（hp 变化时强制显示）
if(!gm.__hpWatchI){
  gm.__hpWatchI=setInterval(function(){
    function watch(p){
      if(!p||!p.isValid)return;
      var h=p.getComponent("HumanController");
      if(!h)return;
      if(h.__lastHp===undefined)h.__lastHp=h.hp;
      if(h.hp!==h.__lastHp){
        h.__lastHp=h.hp;
        // 触发血条显示
        if(h.HealthBar){
          h.HealthBar.getComponent(cc.ProgressBar).progress=h.hp/h.maxhp;
          h.HealthBar.active=true;
          h.hpTimer=3;
        }
      }
    }
    watch(gm.player);
    watch(gm.enemy);
  },100);
}
}
// Quick Ult: 全局 interval（独立于 __applyP）
if(!window.__quInterval){
  window.__quInterval=setInterval(function(){
    if(!window.__passives.p1&&!window.__passives.p2)return;
    var cn2=cc.find("Canvas");if(!cn2)return;
    var gm2=cn2.getComponent("Games");if(!gm2)return;
    function boost(joy,isP1){
      if(!joy||!joy.isValid)return;var jc=joy.getComponent("JoyStick");if(!jc)return;
      // Phoenix 锁定期间不允许大招冷却推进，并把 timer 拉回 0
      if(jc.__phoenixLocked){jc.bigSkillTimer=0;return;}
      var has=(isP1&&window.__passives.p1==="quickUlt")||(!isP1&&window.__passives.p2==="quickUlt");
      if(has&&!jc.bigSkillState){jc.bigSkillTimer+=0.05;} // 每50ms加0.05秒，等于2倍速
    }
    boost(gm2.playerJoy,true);
    boost(gm2.enemyJoy,false);
  },50);
  console.log("[PASSIVE] Quick Ult interval started");
}
