// MirrorImage: 大招触发时召唤分身
// hook _useBigSkill 在我装的的位置已经做过了，这里增加召唤分身
if(!window.__pMirrorWatch){
  window.__pMirrorWatch=setInterval(function(){
    if(!window.__passives.p1&&!window.__passives.p2)return;
    var cn=cc.find("Canvas");if(!cn)return;
    var gm2=cn.getComponent("Games");if(!gm2)return;
    function watch(joy,p,p1){
      if(!joy||!joy.isValid||!p||!p.isValid)return;
      var jc=joy.getComponent("JoyStick");if(!jc)return;
      var has=(p1&&window.__passives.p1==="mirrorImage")||(!p1&&window.__passives.p2==="mirrorImage");
      if(!has)return;
      // 检测大招触发：bigSkillState true 时召唤一次分身
      if(jc.bigSkillState&&!jc.__mirrorSummoned){
        jc.__mirrorSummoned=true;
        try{var h=p.getComponent("Human");if(h&&h.summonAllyItem){
          // 延迟 1 秒确保对手节点完全初始化
          setTimeout(function(){
            try{
              var gm3=cc.find("Canvas").getComponent("Games");
              if(!gm3)return;
              var target=p1?gm3.enemy:gm3.player;
              if(!target||!target.isValid)return;
              var bd=target.getChildByName("body");
              if(!bd)return;
              h.summonAllyItem();
            }catch(e3){}
          },1000);
          // 设置分身 HP=1
          setTimeout(function(){
            try{
              var cn2=cc.find("Canvas");if(!cn2)return;
              cn2.getComponentsInChildren(cc.Component).forEach(function(c2){
                if(!c2.node||!c2.node.isValid)return;
                if(c2.node.name==="AI"&&c2.hp!==undefined&&c2.maxhp!==undefined){
                  if(!c2.__mirrorSet){
                    c2.__mirrorSet=true;
                    c2.hp=1;c2.maxhp=1;
                  }
                }
              });
            }catch(e2){}
          },1500);
          console.log("[P] MirrorImage P"+(p1?1:2));
        }}catch(e){}
      }
      if(!jc.bigSkillState&&jc.__mirrorSummoned)jc.__mirrorSummoned=false;
    }
    watch(gm2.playerJoy,gm2.player,true);
    watch(gm2.enemyJoy,gm2.enemy,false);
  },200);
}

// Evasion: 25% 概率闪避（hook setDamage 头部）
(function(){
  var hookEvasion=setInterval(function(){
    var cn=cc.find("Canvas");if(!cn)return;
    var gm2=cn.getComponent("Games");if(!gm2||!gm2.player||!gm2.player.isValid)return;
    var hc=gm2.player.getComponent("HumanController");if(!hc)return;
    var hcP=Object.getPrototypeOf(hc);
    if(hcP.__pEvas)return;
    var oD=hcP.setDamage;
    hcP.setDamage=function(dmg){
      if(!this.node)return;
      var iP1=this.node.name==="StickMan1";
      var has=(iP1&&window.__passives.p1==="evasion")||(!iP1&&window.__passives.p2==="evasion");
      // 闪避后 0.5s 无敌
      if(has&&this.__evasionInvuln){return;}
      if(has&&Math.random()<0.25){
        // 闪避成功 + 0.5s 无敌
        this.__evasionInvuln=true;
        var selfRef=this;
        setTimeout(function(){selfRef.__evasionInvuln=false;},500);
        // 大号 MISS 特效
        try{var c=cc.find("Canvas");
        var lblE=new cc.Node("evasion");lblE.parent=c;lblE.zIndex=99;
        var pos=this.node.getChildByName("body");
        var bp=pos?pos.parent.convertToWorldSpaceAR(pos.getPosition()):cc.v2(0,0);
        bp=c.convertToNodeSpaceAR(bp);
        lblE.setPosition(bp.x,bp.y+80);
        var lblc=lblE.addComponent(cc.Label);lblc.string="MISS!";lblc.fontSize=64;lblE.color=new cc.Color(120,255,255);
        cc.tween(lblE).to(0.5,{y:lblE.y+100,scale:1.5,opacity:0}).call(function(){if(lblE&&lblE.isValid)lblE.destroy();}).start();}catch(e){}
        console.log("[P] Evasion P"+(iP1?1:2));
        return;
      }
      return oD.call(this,dmg);
    };
    hcP.__pEvas=true;
    clearInterval(hookEvasion);
    console.log("[PASSIVE] Evasion hook installed");
  },500);
})();

// Kamikaze: 濒死时自爆（hp <= 5 触发一次大范围伤害）
// 同归于尽：自己死的瞬间，如果对手 HP<30% 直接炸死对手（自己赢）
(function(){
  var hookKami=setInterval(function(){
    var cn=cc.find("Canvas");if(!cn)return;
    var gm2=cn.getComponent("Games");if(!gm2||!gm2.player||!gm2.player.isValid)return;
    var hc=gm2.player.getComponent("HumanController");if(!hc)return;
    var hcP=Object.getPrototypeOf(hc);
    if(hcP.__pKami)return;
    var oD=hcP.setDamage;
    hcP.setDamage=function(dmg){
      if(!this.node)return;
      var iP1=this.node.name==="StickMan1";
      var has=(iP1&&window.__passives.p1==="kamikaze")||(!iP1&&window.__passives.p2==="kamikaze");
      var willDie=this.hp-dmg<=0;
      if(has&&willDie&&!this.__kamiUsed){
        this.__kamiUsed=true;
        try{
          var gmK=cc.find("Canvas").getComponent("Games");
          var oppN=iP1?gmK.enemy:gmK.player;
          if(oppN&&oppN.isValid){
            var oppHc=oppN.getComponent("HumanController");
            if(oppHc&&!oppHc.isDead){
              var oppRatio=oppHc.hp/oppHc.maxhp;
              if(oppRatio<0.50){
                // 对面血量<50%，直接秒杀（自己赢）
                console.log("[P] 同归于尽触发！对手 HP%="+Math.round(oppRatio*100)+" 炸死");
                var oRoot=Object.getPrototypeOf(oppHc).setDamage;
                oRoot.call(oppHc,oppHc.hp+999);
                // 视觉爆炸（蘑菇云）
                var c=cc.find("Canvas");
                var bd=this.node.getChildByName("body");
                var bp=bd?bd.parent.convertToWorldSpaceAR(bd.getPosition()):cc.v2(0,0);
                bp=c.convertToNodeSpaceAR(bp);
                var bn=new cc.Node("kamiBoom");bn.parent=c;bn.setPosition(bp.x,bp.y);bn.zIndex=99;
                var bg=bn.addComponent(cc.Graphics);
                var br=30;
                var bint=setInterval(function(){
                  if(!bn||!bn.isValid){clearInterval(bint);return;}
                  br+=20;
                  bg.clear();bg.fillColor=new cc.Color(255,Math.max(0,255-br),0,Math.max(0,200-br));
                  bg.circle(0,0,br);bg.fill();
                  if(br>300){clearInterval(bint);if(bn&&bn.isValid)bn.destroy();}
                },30);
                // 屏幕中央"同归于尽！"
                var lblK=new cc.Node("kamiLbl");lblK.parent=c;lblK.zIndex=999;lblK.setPosition(0,100);
                var lblc=lblK.addComponent(cc.Label);lblc.string="💥 同归于尽！💥";lblc.fontSize=72;lblK.color=new cc.Color(255,150,0);
                cc.tween(lblK).to(0.3,{scale:1.8}).delay(1).to(0.5,{opacity:0}).call(function(){if(lblK&&lblK.isValid)lblK.destroy();}).start();
              }else{
                console.log("[P] 同归于尽未触发：对手 HP%="+Math.round(oppRatio*100)+" >= 50%");
              }
            }
          }
        }catch(e){}
      }
      return oD.call(this,dmg);
    };
    hcP.__pKami=true;
    clearInterval(hookKami);
    console.log("[PASSIVE] Kamikaze (同归于尽) hook installed");
  },500);
})();

// AirDash: 离地后持续极速左右移动（不是一次性冲刺）
(function(){
  if(!window.__airDashI){
    window.__airDashI=setInterval(function(){
      var cn=cc.find("Canvas");if(!cn)return;
      var gm2=cn.getComponent("Games");if(!gm2)return;
      function boost(player,isP1){
        if(!player||!player.isValid)return;
        var has=(isP1&&window.__passives.p1==="airDash")||(!isP1&&window.__passives.p2==="airDash");
        if(!has)return;
        var h=player.getComponent("Human");
        if(!h||h._bodyState===0)return; // 地面不加速
        var body=player.getChildByName("body");if(!body)return;
        var rb=body.getComponent(cc.RigidBody);if(!rb)return;
        var v=rb.linearVelocity;
        // 只要有水平速度就大幅加速（×2.5 每帧，封顶 2000）
        if(Math.abs(v.x)>30){
          var newX=v.x*2.5;
          if(Math.abs(newX)>2000)newX=2000*(newX>0?1:-1);
          rb.linearVelocity=cc.v2(newX,v.y);
        }
      }
      boost(gm2.player,true);
      boost(gm2.enemy,false);
    },50);
  }
})();

// (magnetism removed)

// === 新被动 v7 ===

// counterStrike: 受击后 1s 内下一次攻击 ×2
// firstStrike: 开局前 10 秒攻击 ×2
// rage: 累计造成伤害的 30%（封顶 100）追加到下次攻击
// heavyHitter: 大招 ×2（hook BigDamage 不可行，hook setDamage 时检测大招标志）
// cursed: 每秒 -1HP，造成伤害 ×3
// executor: 对手 HP 越低伤害越高（线性 ×1 ~ ×3）
// executioner: 大招对 HP<25% 必杀
// fortress: 站立 1s 后受到伤害 ×0.25
// unstoppable: 免疫击退（每帧把击退冲量清零）
// lifeline: HP 首次降到 50% 回满
// cleric: 受击 50% 概率 +10HP
// bigBoy: 体型 +30%, maxhp +30%, 攻击 +30%
// tinyBoy: 体型 -40%, 移速 +30%, 大招冷却 -50%
(function(){
  var hookNew=setInterval(function(){
    var cn=cc.find("Canvas");if(!cn)return;
    var gm2=cn.getComponent("Games");if(!gm2||!gm2.player||!gm2.player.isValid)return;
    var hc=gm2.player.getComponent("HumanController");if(!hc)return;
    var hcP=Object.getPrototypeOf(hc);
    if(hcP.__pV7)return;
    // 记录每个玩家的 fortress 静止计时、firstStrike 开始时间、累计伤害
    if(!gm2.__roundStart)gm2.__roundStart=Date.now();
    var oD=hcP.setDamage;
    hcP.setDamage=function(dmg){
      if(!this.node)return;
      // === 进入 setDamage 前先清理过期的无敌标志 ===
      try{
        if(this.isInvincible){
          // 道具 80（黄金穹顶）正常情况下有 __invincibleEnd
          if(this.__invincibleEnd){
            if(Date.now()>=this.__invincibleEnd){
              this.isInvincible=false;
              this.__invincibleEnd=null;
              this.__invincibleStart=null;
            }
          }else if(this.__invincibleStart){
            // 没有合法的 end 标记，超过 1.5 秒就清
            if(Date.now()-this.__invincibleStart>1500){
              this.isInvincible=false;
              this.__invincibleStart=null;
            }
          }else{
            this.__invincibleStart=Date.now();
          }
        }
        if(this.isShieldInvincible){
          if(this.__shieldInvStart&&Date.now()-this.__shieldInvStart>500){
            this.isShieldInvincible=false;
            this.isSlowShieldTimer=null;
            this.__shieldInvStart=null;
          }else if(!this.__shieldInvStart){
            this.__shieldInvStart=Date.now();
          }
        }
      }catch(_){}
      var iP1=this.node.name==="StickMan1";
      var aP1=!iP1;
      var atkPassive=aP1?window.__passives.p1:window.__passives.p2;
      var defPassive=iP1?window.__passives.p1:window.__passives.p2;
      var atkHc=null;
      try{var gmA=cc.find("Canvas").getComponent("Games");
      var atkN=aP1?gmA.player:gmA.enemy;
      if(atkN&&atkN.isValid)atkHc=atkN.getComponent("HumanController");}catch(e){}
      // === 攻击者侧 buff ===
      // heavyHitter: 大招期间伤害 ×2
      if(atkPassive==="heavyHitter"&&atkHc&&atkHc.__inBigSkill)dmg=Math.round(dmg*1.5);
      // oneShot 碰一下试试：伤害 ×5
      if(atkPassive==="oneShot")dmg=Math.round(dmg*3);
      // firstStrike: 开局 6s 内 ×2
      if(atkPassive==="firstStrike"&&Date.now()-gm2.__roundStart<6000)dmg=Math.round(dmg*2);
      // counterStrike: 上次受击 1s 内下次攻击 ×2
      if(atkPassive==="counterStrike"&&atkHc&&atkHc.__counterReady){
        atkHc.__counterReady=false;
        dmg=Math.round(dmg*2);
      }
      // rage: 累计伤害 30%
      if(atkPassive==="rage"&&atkHc){
        if(!atkHc.__rageTotal)atkHc.__rageTotal=0;
        var bonus=Math.min(100,Math.round(atkHc.__rageTotal*0.30));
        dmg+=bonus;
      }
      // cursed: 伤害 ×2
      if(atkPassive==="cursed")dmg=Math.round(dmg*2);
      // executor: 对手 HP 越低 ×1 ~ ×3 线性
      if(atkPassive==="executor"){
        var ratio=this.hp/this.maxhp;
        var mult=1+2*(1-ratio); // ratio=1: ×1, ratio=0: ×3
        dmg=Math.round(dmg*mult);
      }
      // 终结者: 普通攻击斩杀（对手血越低概率越高，HP=0% → 100%, HP=100% → 0%）
      if(atkPassive==="executioner"){
        var ratioE=this.hp/this.maxhp;
        var killChance=1-ratioE;
        if(Math.random()<killChance){
          dmg=this.hp+999;
          console.log("[P] Executioner 斩杀！对手 HP%="+Math.round(ratioE*100)+" 几率="+Math.round(killChance*100)+"%");
        }
      }
      // bigBoy: 攻击 +30%
      if(atkPassive==="bigBoy")dmg=Math.round(dmg*1.30);
      // === 第六批新被动（攻击者侧） ===
      // compound 等我发育：每层 +8% 伤害（层数在 V7 累积）
      if(atkPassive==="compound"&&atkHc){
        var atkNodeC=aP1?(cc.find("Canvas").getComponent("Games").player):(cc.find("Canvas").getComponent("Games").enemy);
        var stk=(atkNodeC&&atkNodeC.__compoundStacks)||0;
        if(stk>0)dmg=Math.round(dmg*(1+0.08*stk));
      }
      // disarmer 拿来吧你：命中 25% 概率打掉对手武器 2 秒
      if(atkPassive==="disarmer"&&dmg>0&&!this.isDead&&Math.random()<0.30){
        try{
          var defNode=this.node;
          var defWeapons=[];
          defNode.children.forEach(function(ch){
            if(ch.group==="weapons1"||ch.group==="weapons2"){defWeapons.push(ch);}
          });
          if(defWeapons.length){
            defWeapons.forEach(function(wn){wn.active=false;});
            var dHc=this;
            if(dHc)dHc.__disarmEnd=Date.now()+2000;
            if(window.__toastNearPlayer)window.__toastNearPlayer("🚫 缴械!",defNode,new cc.Color(255,180,80),24);
            setTimeout(function(){defWeapons.forEach(function(wn){if(wn&&wn.isValid)wn.active=true;});},2000);
          }
        }catch(_){}
      }
      // === 第三批新被动（攻击者侧） ===
      // mage 法师：伤害 -50%（cd 减少在 V7 interval 处理）
      if(atkPassive==="mage")dmg=Math.round(dmg*0.5);
      // gambler 赌徒：20% 概率直接斩杀对手
      if(atkPassive==="gambler"){
        if(Math.random()<0.2&&!this.isDead){
          dmg=Math.max(dmg,this.hp+1); // 让伤害 >= 当前 HP，触发死亡
          console.log("[P] Gambler 斩杀！");
          if(window.__toastNearPlayer)window.__toastNearPlayer("🎲 斩！",this.node,new cc.Color(255,50,50),32);
        }
      }
      // thunderer 雷神：开局 HP -20% 在 GC 同位置处理
      // === 第三批新被动（防御者侧） ===
      // unyielding 不灭斗士：HP<25% 时减伤 50%
      if(defPassive==="unyielding"&&this.hp<=this.maxhp*0.25)dmg=Math.round(dmg*0.5);
      // === 第六批：echo 伤害在路上 ===
      // 受到的伤害不立即结算，加入延迟队列（2秒后扣），期间可被治疗抵消
      if(defPassive==="echo"&&dmg>0&&!this.isDead&&dmg<200){
        if(!this.__echoQueue)this.__echoQueue=[];
        dmg=window.__capBudgetedItemDamage(this,dmg);
        if(dmg<=0)return;
        this.__echoQueue.push({dmg:dmg,t:Date.now()+2000});
        if(window.__toastNearPlayer)window.__toastNearPlayer("⏳ -"+dmg,this.node,new cc.Color(180,140,255),20);
        this.flash&&this.flash();
        return; // 不立即扣血
      }
      // === 防御者侧 ===
      // 反伤盾（一次性 / 5s）：把伤害反弹给攻击者
      var reflected=false;
      if((this.__reflectOnce||this.__reflectActive)&&dmg>0&&atkHc&&!atkHc.isDead){
        try{
          var oRefl=Object.getPrototypeOf(atkHc).setDamage;
          oRefl.call(atkHc,dmg);
          if(this.__reflectOnce){
            this.__reflectOnce=false;
            // 移除光环
            var bdR=this.node.getChildByName("body");
            if(bdR){var auR=bdR.getChildByName("reflectAura");if(auR)auR.destroy();}
          }
          reflected=true;
          console.log("[ITEM] Reflect "+dmg);
        }catch(eR){}
      }
      // fortress: 站立不动 1s 减免 75%
      if(defPassive==="fortress"&&this.__fortressStill>1)dmg=Math.round(dmg*0.25);
      // counterStrike (受害者): 标记 1s 内下次攻击 ×2
      if(defPassive==="counterStrike"){
        this.__counterReady=true;
        var selfRef=this;
        setTimeout(function(){selfRef.__counterReady=false;},1000);
      }
      // cleric: 50% 概率回 10 HP
      if(defPassive==="cleric"&&Math.random()<0.50&&!this.isDead){
        this.hp=Math.min(this.maxhp,this.hp+10);
        if(this.HealthBar){var pbC=this.HealthBar.getComponent(cc.ProgressBar);if(pbC)pbC.progress=this.hp/this.maxhp;}
        try{var cnC=cc.find("Canvas");
        var lblC=new cc.Node("clericHeal");lblC.parent=cnC;lblC.zIndex=99;
        var posCC=this.node.getChildByName("body");
        var bp=posCC?posCC.parent.convertToWorldSpaceAR(posCC.getPosition()):cc.v2(0,0);
        bp=cnC.convertToNodeSpaceAR(bp);
        lblC.setPosition(bp.x,bp.y+80);
        var lblcc=lblC.addComponent(cc.Label);lblcc.string="+10";lblcc.fontSize=32;lblC.color=new cc.Color(120,255,120);
        cc.tween(lblC).to(0.6,{y:lblC.y+80,opacity:0}).call(function(){if(lblC&&lblC.isValid)lblC.destroy();}).start();}catch(e){}
      }
      // 调用原版 setDamage
      var hpBefore=this.hp;
      var r=oD.call(this,dmg);
      // 检测击杀（HP 从正变 ≤0）
      var killed=hpBefore>0&&this.hp<=0;
      // healPriest 治愈祭司：大招命中回 10HP
      if(atkPassive==="healPriest"&&atkHc&&atkHc.__inBigSkill&&!atkHc.isDead){
        atkHc.hp=Math.min(atkHc.maxhp,atkHc.hp+10);
        if(atkHc.HealthBar){var pbHP=atkHc.HealthBar.getComponent(cc.ProgressBar);if(pbHP)pbHP.progress=atkHc.hp/atkHc.maxhp;}
      }
      // 嗜血斩道具（state 64）：命中回 30 HP，触发后清除标志
      if(atkHc&&atkHc.__bloodthirstReady&&dmg>0){
        atkHc.__bloodthirstReady=false;
        if(!atkHc.isDead){
          atkHc.hp=Math.min(atkHc.maxhp,atkHc.hp+30);
          if(atkHc.HealthBar){var pbBT=atkHc.HealthBar.getComponent(cc.ProgressBar);if(pbBT)pbBT.progress=atkHc.hp/atkHc.maxhp;}
          console.log("[ITEM] 嗜血斩 +30HP");
        }
      }
      // pyromancer 你火了：命中时让对手着火 3 秒
      if(atkPassive==="pyromancer"&&dmg>0&&!this.isDead){
        this.__burnEnd=Date.now()+3000;
        this.__burnDamage=3; // 每秒掉血
        // 视觉
        try{var bdF=this.node.getChildByName("body");
        if(bdF){var oldFa=bdF.getChildByName("fireAura");if(oldFa)oldFa.destroy();
          var fa=new cc.Node("fireAura");fa.parent=bdF;fa.zIndex=-1;
          var fag=fa.addComponent(cc.Graphics);
          fag.fillColor=new cc.Color(255,100,0,150);fag.circle(0,0,60);fag.fill();
          setTimeout(function(){if(fa&&fa.isValid)fa.destroy();},3000);
        }}catch(e){}
      }
      // frostlord 冷静一点：命中时减速对手 3 秒（明显减速 + 视觉提示）
      if(atkPassive==="frostlord"&&dmg>0&&!this.isDead){
        // 被害者有寒霜免疫则跳过
        if(defPassive!=="frostImmune"){
          this.node.__frostlordUntil=Date.now()+3000;
          // 蓝色寒冰光环视觉
          try{var bdFL=this.node.getChildByName("body");
          if(bdFL){var oldFL=bdFL.getChildByName("frostlordAura");if(oldFL)oldFL.destroy();
            var fl=new cc.Node("frostlordAura");fl.parent=bdFL;fl.zIndex=-1;
            var flg=fl.addComponent(cc.Graphics);
            flg.fillColor=new cc.Color(120,200,255,140);flg.circle(0,0,55);flg.fill();
            flg.lineWidth=4;flg.strokeColor=new cc.Color(80,160,255,220);flg.circle(0,0,55);flg.stroke();
            setTimeout(function(){if(fl&&fl.isValid)fl.destroy();},3000);
          }}catch(e){}
        }
      }
      // === 第四批新被动（攻击者侧） ===
      // sharpshooter 神射手：远程武器 +40%（远程 = 武器 isGun/isSniper/isHarp 等）
      if(atkPassive==="sharpshooter"&&atkHc){
        try{
          var atkN2=aP1?cc.find("Canvas").getComponent("Games").player:cc.find("Canvas").getComponent("Games").enemy;
          if(atkN2){
            var weap=atkN2.children.find(function(ch){return ch.group==="weapons1"||ch.group==="weapons2";});
            if(weap){
              var w=weap.getComponent(cc.Component);
              // 检测远程武器（任一标志为真）
              var isRanged=false;
              weap.getComponents(cc.Component).forEach(function(c){
                if(c.isGun||c.isSniper||c.isHarp)isRanged=true;
              });
              if(isRanged)dmg=Math.round(dmg*1.30);
            }
          }
        }catch(_){}
      }
      // 记录 rage 累计伤害（原版处理后）
      if(atkPassive==="rage"&&atkHc&&dmg>0){
        if(!atkHc.__rageTotal)atkHc.__rageTotal=0;
        atkHc.__rageTotal+=dmg;
      }
      // === 第四批：foodie / frostImmune 在道具拾取处和被动 hooks 处理（不在 setDamage 里）===
      return r;
    };
    hcP.__pV7=true;
    clearInterval(hookNew);
    console.log("[PASSIVE] V7 hooks installed");
  },500);
})();

// V7 全局 interval：监控 fortress 静止 + bigSkill 标志 + cursed 掉血 + unstoppable + bigBoy/tinyBoy 体型
if(!window.__pV7Int){
  window.__pV7Int=setInterval(function(){
    var cn=cc.find("Canvas");if(!cn)return;
    var gm2=cn.getComponent("Games");if(!gm2)return;
    function tick(p,joy,p1){
      if(!p||!p.isValid)return;
      var passive=p1?window.__passives.p1:window.__passives.p2;
      var hc=p.getComponent("HumanController");
      if(!hc)return;
      var body=p.getChildByName("body");
      var rb=body?body.getComponent(cc.RigidBody):null;
      // 兜底：isInvincible 持续超过预期则强制还原
      if(hc.isInvincible){
        if(!hc.__invincibleStart)hc.__invincibleStart=Date.now();
        var dur=Date.now()-hc.__invincibleStart;
        // 如果有 __invincibleEnd 标记（道具 80 等），用它做参考
        var allowed=1500; // 默认最多 1.5 秒（够 grappin/钩爪的 0.05s + cc.tween 缓冲）
        if(hc.__invincibleEnd){
          var remain=hc.__invincibleEnd-Date.now();
          if(remain>0)allowed=remain+500; // 还在合法期内，延长 0.5s 缓冲
          else allowed=0; // 已经过期，立刻强制还原
        }
        if(dur>allowed){
          console.log("[FIX] 强制还原 isInvincible (持续 "+dur+"ms, allowed="+allowed+"ms)");
          hc.isInvincible=false;
          hc.__invincibleStart=null;
          hc.__invincibleEnd=null;
        }
      }else{
        hc.__invincibleStart=null;
      }
      // isShieldInvincible 兜底（原版护盾无敌也可能卡住）
      if(hc.isShieldInvincible){
        if(!hc.__shieldInvStart)hc.__shieldInvStart=Date.now();
        if(Date.now()-hc.__shieldInvStart>500){
          console.log("[FIX] 强制还原 isShieldInvincible");
          hc.isShieldInvincible=false;
          hc.isSlowShieldTimer=null;
          hc.__shieldInvStart=null;
        }
      }else{
        hc.__shieldInvStart=null;
      }
      // 玩家血量翻倍（持续监控：只要 maxhp 是默认值 50，就改成 100）
      if(hc&&hc.maxhp===50){
        hc.maxhp=100;
        hc.hp=hc.hp===50?100:hc.hp*2;
        if(hc.HealthBar){var pbHpD=hc.HealthBar.getComponent(cc.ProgressBar);if(pbHpD)pbHpD.progress=hc.hp/hc.maxhp;}
      }
      // oneShot 碰一下试试：maxhp = 10
      if(passive==="oneShot"&&hc&&!p.__oneShotApplied){
        p.__oneShotApplied=true;
        hc.maxhp=10;
        hc.hp=10;
        if(hc.HealthBar){var pbOS=hc.HealthBar.getComponent(cc.ProgressBar);if(pbOS)pbOS.progress=1;}
      }
      // pyromancer 烈焰：被动持续掉血处理
      if(p.__burnEnd&&Date.now()<p.__burnEnd&&hc&&!hc.isDead){
        if(!p.__burnTick)p.__burnTick=0;
        p.__burnTick+=0.05;
        if(p.__burnTick>=1){
          p.__burnTick=0;
          hc.hp=Math.max(0,hc.hp-3);
          if(hc.HealthBar){var pbB=hc.HealthBar.getComponent(cc.ProgressBar);if(pbB)pbB.progress=hc.hp/hc.maxhp;}
        }
      }
      // fortress/gargoyle: 摇杆不动就触发（检测 JoyStick.stopMove）
      if((passive==="fortress"||passive==="gargoyle")&&rb){
        var joyNode=p1?gm2.playerJoy:gm2.enemyJoy;
        var jcF=joyNode&&joyNode.isValid?joyNode.getComponent("JoyStick"):null;
        var isStill=true;
        if(jcF){
          if(jcF.stopMove)isStill=false;
        }
        // 也检查全局 P1Run/P2Run
        var cfg=cc.find("Canvas")&&cc.find("Canvas").getComponent("Games");
        if(cfg){
          var gc=window.__require&&window.__require("ConfigManager");
          if(!gc)try{gc=require("ConfigManager");}catch(e){}
          if(gc&&gc.gameConfig){
            if(p1&&gc.gameConfig.P1Run)isStill=false;
            if(!p1&&gc.gameConfig.P2Run)isStill=false;
          }
        }
        if(isStill){
          p.__fortressStill=(p.__fortressStill||0)+0.05;
          hc.__fortressStill=p.__fortressStill;
        }else{p.__fortressStill=0;hc.__fortressStill=0;}
      }
      // unstoppable: 免疫击退（每帧强制清除异常速度）
      if(passive==="unstoppable"&&rb){
        var v2=rb.linearVelocity;
        if(Math.abs(v2.x)>500)rb.linearVelocity=cc.v2(500*(v2.x>0?1:-1),v2.y);
        if(Math.abs(v2.y)>1000)rb.linearVelocity=cc.v2(rb.linearVelocity.x,1000*(v2.y>0?1:-1));
      }
      // cursed: 每秒 -1HP（每 50ms 减 0.05，约 1/s）
      if(passive==="cursed"&&hc&&!hc.isDead&&hc.hp>1){
        if(!p.__cursedTick)p.__cursedTick=0;
        p.__cursedTick+=0.05;
        if(p.__cursedTick>=1){p.__cursedTick=0;hc.hp-=1;
          if(hc.HealthBar){var pbCu=hc.HealthBar.getComponent(cc.ProgressBar);if(pbCu)pbCu.progress=hc.hp/hc.maxhp;}}
      }
      // bigBoy: 体型放大 + maxhp +30%
      if(passive==="bigBoy"&&!p.__bbApplied){
        p.__bbApplied=true;
        p.scale*=1.3;
        if(hc){hc.maxhp=Math.round(hc.maxhp*1.3);hc.hp=hc.maxhp;
        if(hc.HealthBar){var pbBB=hc.HealthBar.getComponent(cc.ProgressBar);if(pbBB)pbBB.progress=1;}}
        // 调整关节
        try{p.getComponentsInChildren(cc.Joint).forEach(function(j){
          if(j.anchor){j.anchor=cc.v2(j.anchor.x*1.3,j.anchor.y*1.3);j.apply&&j.apply();}
          if(j.connectedAnchor){j.connectedAnchor=cc.v2(j.connectedAnchor.x*1.3,j.connectedAnchor.y*1.3);j.apply&&j.apply();}
        });}catch(e){}
        console.log("[P] BigBoy applied P"+(p1?1:2));
      }
      // tinyBoy: 体型缩小 + 移速 + 大招冷却
      if(passive==="tinyBoy"&&!p.__tbApplied){
        p.__tbApplied=true;
        p.scale*=0.6;
        try{p.getComponentsInChildren(cc.Joint).forEach(function(j){
          if(j.anchor){j.anchor=cc.v2(j.anchor.x*0.6,j.anchor.y*0.6);j.apply&&j.apply();}
          if(j.connectedAnchor){j.connectedAnchor=cc.v2(j.connectedAnchor.x*0.6,j.connectedAnchor.y*0.6);j.apply&&j.apply();}
        });}catch(e){}
        console.log("[P] TinyBoy applied P"+(p1?1:2));
      }
      if(passive==="tinyBoy"&&rb){
        var v3=rb.linearVelocity;
        if(Math.abs(v3.x)>20)rb.linearVelocity=cc.v2(v3.x*1.3,v3.y);
        if(joy&&joy.isValid){var jc=joy.getComponent("JoyStick");if(jc&&!jc.bigSkillState)jc.bigSkillTimer+=1/60;}
      }
      // === 第三批新被动 V7 处理 ===
      // gargoyle 石像鬼：站立不动 1s 后回血 5HP/s
      if(passive==="gargoyle"&&hc&&!hc.isDead&&p.__fortressStill>1){
        if(!p.__gargoyleTick)p.__gargoyleTick=0;
        p.__gargoyleTick+=0.05;
        if(p.__gargoyleTick>=1){p.__gargoyleTick=0;
          if(hc.hp<hc.maxhp){hc.hp=Math.min(hc.maxhp,hc.hp+5);
            if(hc.HealthBar){var pbG=hc.HealthBar.getComponent(cc.ProgressBar);if(pbG)pbG.progress=hc.hp/hc.maxhp;}
          }
        }
      }
      // mage 法师：大招冷却 -75%
      if(passive==="mage"&&joy&&joy.isValid){
        var jcM=joy.getComponent("JoyStick");
        if(jcM&&!jcM.bigSkillState)jcM.bigSkillTimer+=0.15; // 每 50ms +0.15 ≈ 75% 加速
      }
      // thunderer 雷神：移速 +30%，HP 上限一次性 -20%
      if(passive==="thunderer"){
        if(rb){var v4=rb.linearVelocity;if(Math.abs(v4.x)>20)rb.linearVelocity=cc.v2(v4.x*1.3,v4.y);}
        if(hc&&!p.__thundererApplied){
          p.__thundererApplied=true;
          var nm=Math.round(hc.maxhp*0.8);
          hc.maxhp=nm;hc.hp=Math.min(hc.hp,nm);
          if(hc.HealthBar){var pbT=hc.HealthBar.getComponent(cc.ProgressBar);if(pbT)pbT.progress=hc.hp/hc.maxhp;}
          console.log("[P] Thunderer P"+(p1?1:2)+" maxhp -20%");
        }
      }
      // 寒冰诅咒道具：移速大幅降低 -70%（每 50ms 强制压速）
      if(p.__frostUntil&&Date.now()<p.__frostUntil&&rb){
        var vF=rb.linearVelocity;
        // 限制水平速度上限（强行减速）
        var maxSpeed=120;
        if(Math.abs(vF.x)>maxSpeed)rb.linearVelocity=cc.v2(maxSpeed*(vF.x>0?1:-1),vF.y);
      }
      // frostlord 冷静一点减速：水平速度上限 80（比道具更狠，命中即触发）
      if(p.__frostlordUntil&&Date.now()<p.__frostlordUntil&&rb){
        var vFL=rb.linearVelocity;
        if(Math.abs(vFL.x)>80)rb.linearVelocity=cc.v2(80*(vFL.x>0?1:-1),vFL.y);
      }
      // 沉默道具（state 74）：阻止大招充能
      if(hc&&hc.__silenced&&joy&&joy.isValid){
        var jcSil=joy.getComponent("JoyStick");
        if(jcSil&&!jcSil.bigSkillState)jcSil.bigSkillTimer=0;
      }
      // 反向操作道具（state 110）：在 V7 里反转水平速度
      if(p.__invertControlEnd&&Date.now()<p.__invertControlEnd&&rb){
        var vI=rb.linearVelocity;
        if(Math.abs(vI.x)>20)rb.linearVelocity=cc.v2(-vI.x,vI.y);
      }
      // 镜像反转道具（state 75）：持续翻转 scaleX
      if(p.__mirrorFlip&&rb){
        var vM=rb.linearVelocity;
        // 反转移动方向
        if(Math.abs(vM.x)>20)rb.linearVelocity=cc.v2(-vM.x,vM.y);
      }
      // === 第六批新被动 per-frame ===
      // bulwark 躺平了：静止 0.6s 后获得护盾(onceShield)，移动则失去
      if(passive==="bulwark"&&hc&&!hc.isDead){
        var movingBW=false;
        if(rb){var vbw=rb.linearVelocity;if(Math.abs(vbw.x)>30)movingBW=true;}
        if(p1&&gm2){var gcBW=window.__require&&window.__require("ConfigManager");if(gcBW&&gcBW.gameConfig&&gcBW.gameConfig.P1Run)movingBW=true;}
        if(!p1&&gm2){var gcBW2=window.__require&&window.__require("ConfigManager");if(gcBW2&&gcBW2.gameConfig&&gcBW2.gameConfig.P2Run)movingBW=true;}
        if(movingBW){
          p.__bulwarkStill=0;
          // 移动则护盾消失
          if(hc.__bulwarkShield&&hc.onceShield>0){
            hc.onceShield=0;hc.__bulwarkShield=false;
            try{var sn=p.getComponent("Human");if(sn&&sn.shieldsNode)sn.shieldsNode.active=false;}catch(_){}
          }
        }else{
          p.__bulwarkStill=(p.__bulwarkStill||0)+0.05;
          if(p.__bulwarkStill>0.6&&!hc.__bulwarkShield&&(!hc.onceShield||hc.onceShield<=0)){
            hc.onceShield=1;hc.__bulwarkShield=true;
            try{var sn2=p.getComponent("Human");if(sn2&&sn2.sheildItem)sn2.sheildItem();}catch(_){}
            if(window.__toastNearPlayer)window.__toastNearPlayer("🛡 护盾",p,new cc.Color(150,200,255),22);
          }
        }
      }
      // compound 等我发育：存活每 5 秒永久 +8% 伤害 + 移速逐渐提升
      if(passive==="compound"&&hc&&!hc.isDead){
        if(!p.__compoundStart)p.__compoundStart=Date.now();
        var stacksC=Math.floor((Date.now()-p.__compoundStart)/5000);
        if(stacksC>(p.__compoundStacks||0)){
          p.__compoundStacks=stacksC;
          if(window.__toastNearPlayer)window.__toastNearPlayer("❄ 雪球 x"+stacksC,p,new cc.Color(180,230,255),22);
        }
        // 移速随层数提升（上限 +40%）
        if(rb){var mult=1+Math.min(0.4,(p.__compoundStacks||0)*0.08);var vc=rb.linearVelocity;
          if(Math.abs(vc.x)>20)rb.linearVelocity=cc.v2(vc.x*mult,vc.y);}
      }
      // echo 伤害在路上：延迟伤害结算 —— 每帧把到期的延迟伤害实际扣掉
      if(hc&&hc.__echoQueue&&hc.__echoQueue.length){
        var nowE=Date.now();
        var remain=[];
        hc.__echoQueue.forEach(function(ed){
          if(nowE>=ed.t){
            // 结算（用原版扣血，但走未 hook 的底层避免再次进 echo）
            if(!hc.isDead&&hc.hp>0){
              if(!(window.__resolveFatalProtection&&window.__resolveFatalProtection(hc,ed.dmg)))hc.hp-=ed.dmg;
              if(hc.HealthBar){var pbE=hc.HealthBar.getComponent(cc.ProgressBar);if(pbE)pbE.progress=Math.max(0,hc.hp/hc.maxhp);}
              if(hc.hp<=0){hc.hp=0;}
            }
          }else remain.push(ed);
        });
        hc.__echoQueue=remain;
      }
      // 监测大招状态 - 标记 atkHc.__inBigSkill 用于 heavyHitter/executioner
      if(joy&&joy.isValid){
        var jc2=joy.getComponent("JoyStick");
        if(jc2&&hc){hc.__inBigSkill=jc2.bigSkillState||false;}
      }
    }
    tick(gm2.player,gm2.playerJoy,true);
    tick(gm2.enemy,gm2.enemyJoy,false);
  },50);
}

// 重置 roundStart 在新回合
(function(){
  setInterval(function(){
    var cn=cc.find("Canvas");if(!cn)return;
    var gm2=cn.getComponent("Games");if(!gm2||!gm2.player||!gm2.player.isValid)return;
    var rk=(gm2.player.uuid||gm2.player._id||"")+"|"+(gm2.enemy?(gm2.enemy.uuid||gm2.enemy._id||""):"");
    if(window.__lastV7RoundKey!==rk){
      window.__lastV7RoundKey=rk;
      gm2.__roundStart=Date.now();
      // 清理状态
      [gm2.player,gm2.enemy].forEach(function(p){
        if(!p||!p.isValid)return;
        p.__fortressStill=0;
        p.__cursedTick=0;
        p.__bbApplied=false;
        p.__tbApplied=false;
        var hc=p.getComponent("HumanController");
        if(hc){hc.__lifelineUsed=false;hc.__rageTotal=0;hc.__counterReady=false;}
      });
    }
  },500);
})();

window.passive=function(p1,p2){
  if(!p1){console.log("被动: doubleJump(二段跳) ricochet(弹射物) spikeImmune(尖刺免疫) lifesteal(吸血)");
  console.log("当前: P1="+(window.__passives.p1||"无")+" P2="+(window.__passives.p2||"无"));return;}
  window.__passives.p1=p1;if(p2)window.__passives.p2=p2;
};

// 我装的觉醒：所有数值爆表 + 反复复活对手让觉醒方蹂躏
// reapply=true 表示新回合再次应用（已觉醒）
window.__triggerSillyAwakening=function(gm,isP1,reapply){
  if(!gm||!gm.player||!gm.player.isValid)return;
  var hc=isP1?gm.player.getComponent("HumanController"):(gm.enemy&&gm.enemy.getComponent("HumanController"));
  if(!hc)return;
  // 对手 hc 用于反复复活
  var opp=isP1?gm.enemy:gm.player;
  var oppHc=opp&&opp.isValid?opp.getComponent("HumanController"):null;
  var node=isP1?gm.player:gm.enemy;
  if(!reapply){
    if(isP1)window.__sillyAwakenedP1=true;else window.__sillyAwakenedP2=true;
    console.log("=========================");
    console.log("[我装的觉醒] P"+(isP1?1:2)+" 全屏特效启动！数值爆表！对手反复复活被蹂躏！");
    console.log("=========================");
    // === 屏幕中央巨型震撼文字 ===
    try{
      var cn=cc.find("Canvas");
      // 黑色暗角
      var dark=new cc.Node("sillyDark");dark.parent=cn;dark.setPosition(0,0);dark.zIndex=997;
      var sz0=cc.winSize;
      dark.setContentSize(sz0.width*2,sz0.height*2);
      var dsp=dark.addComponent(cc.Sprite);
      var dtex=new cc.Texture2D();
      var darr=new Uint8Array([0,0,0,255]);
      dtex.initWithData(darr,cc.Texture2D.PixelFormat.RGBA8888,1,1);
      dsp.spriteFrame=new cc.SpriteFrame(dtex);
      dsp.sizeMode=cc.Sprite.SizeMode.CUSTOM;
      dark.opacity=0;
      cc.tween(dark).to(0.3,{opacity:200}).delay(2).to(0.5,{opacity:0}).call(function(){if(dark&&dark.isValid)dark.destroy();}).start();

      // 多层标题
      var titleParent=new cc.Node("sillyTitleParent");titleParent.parent=cn;titleParent.setPosition(0,0);titleParent.zIndex=999;
      // 主标题
      var t=new cc.Node("sillyTitle");t.parent=titleParent;t.setPosition(0,40);
      var l=t.addComponent(cc.Label);
      l.string="🤡 我装的进化成究极我装的 🤡";l.fontSize=110;l.lineHeight=130;
      t.color=new cc.Color(255,40,40);
      // 副标题
      var sub=new cc.Node("sillySubtitle");sub.parent=titleParent;sub.setPosition(0,-80);
      var sl=sub.addComponent(cc.Label);
      sl.string="P"+(isP1?1:2)+" 进化完成";sl.fontSize=42;
      sub.color=new cc.Color(255,200,0);
      // 闪光圆
      var ring=new cc.Node("sillyRing");ring.parent=titleParent;ring.setPosition(0,0);ring.zIndex=-1;
      var rg=ring.addComponent(cc.Graphics);
      var rci=0;var ringColors=[cc.Color.RED,cc.Color.YELLOW,cc.Color.MAGENTA,cc.Color.CYAN];
      var ringInt=setInterval(function(){
        if(!ring||!ring.isValid){clearInterval(ringInt);return;}
        rg.clear();
        for(var ri=0;ri<5;ri++){
          rg.lineWidth=8;
          rg.strokeColor=ringColors[(rci+ri)%ringColors.length];
          rg.circle(0,0,100+ri*60+Math.sin(Date.now()/100+ri)*20);
          rg.stroke();
        }
        rci++;
      },50);
      // 入场动画：放大 -> 抖动 -> 淡出
      titleParent.scale=0.1;
      cc.tween(titleParent)
        .to(0.4,{scale:2},{easing:'backOut'})
        .to(0.1,{scale:1.7})
        .to(0.1,{scale:2})
        .to(0.1,{scale:1.7})
        .to(0.1,{scale:2})
        .delay(1.5)
        .to(0.5,{scale:3,opacity:0})
        .call(function(){if(titleParent&&titleParent.isValid)titleParent.destroy();})
        .start();
      // 标题颜色循环
      var tci=0;
      var titleColors=[new cc.Color(255,40,40),new cc.Color(255,150,0),new cc.Color(255,255,0),new cc.Color(0,255,100),new cc.Color(0,200,255),new cc.Color(255,0,255)];
      var titleInt=setInterval(function(){if(!t||!t.isValid){clearInterval(titleInt);return;}t.color=titleColors[tci%titleColors.length];tci++;},100);
    }catch(e){console.log("[我装的] title err",e.message);}
    // 全屏彩色闪烁 overlay（持续）
    try{
      var cn2=cc.find("Canvas");
      var ov=new cc.Node("sillyOverlay");ov.parent=cn2;ov.setPosition(0,0);ov.zIndex=996;
      var sz=cc.winSize;
      ov.setContentSize(sz.width*1.5,sz.height*1.5);
      var sp=ov.addComponent(cc.Sprite);
      var tex=new cc.Texture2D();
      var arr=new Uint8Array([255,255,255,255]);
      tex.initWithData(arr,cc.Texture2D.PixelFormat.RGBA8888,1,1);
      sp.spriteFrame=new cc.SpriteFrame(tex);
      sp.sizeMode=cc.Sprite.SizeMode.CUSTOM;
      ov.opacity=80;
      window.__sillyOverlay=ov;
      var ovColors=[cc.Color.RED,cc.Color.YELLOW,cc.Color.GREEN,cc.Color.CYAN,cc.Color.BLUE,cc.Color.MAGENTA,new cc.Color(255,128,0),new cc.Color(255,0,128)];
      var oi=0;
      var ovInt=setInterval(function(){
        if(!ov||!ov.isValid){clearInterval(ovInt);return;}
        ov.color=ovColors[oi%ovColors.length];
        ov.opacity=40+Math.random()*40;
        oi++;
      },100);
      window.__sillyOverlayInt=ovInt;
    }catch(e){console.log("[我装的] overlay err",e.message);}
    // 锁定 isShowFinishView=false（防止结算）
    try{
      var configMgrSearch=null;
      // 注入一个守护：覆盖 isShowFinishView 属性
      var gmGuard=cc.find("Canvas").getComponent("Games");
      if(gmGuard){
        // 通过遍历查找 ConfigManager 的 gameConfig
        var found=false;
        for(var k in gmGuard){
          var v=gmGuard[k];
          if(v&&typeof v==="object"&&"isShowFinishView" in v){
            window.__sillyGameConfig=v;
            console.log("[我装的] gameConfig located via gm."+k);
            found=true;
            break;
          }
        }
      }
    }catch(e){}
  }
  // 觉醒方=进化版我装的：保持普通血量（可杀死），只是属性大幅下降
  // 不设 9999，否则永远打不死
  if(hc.maxhp&&hc.maxhp<=100)hc.maxhp=100;
  if(hc.hp>hc.maxhp)hc.hp=hc.maxhp;
  // 复活只在第一次进入觉醒时给满血，之后回合保持原状
  if(!reapply){
    hc.hp=hc.maxhp;
    hc.isDead=false;
    if(hc.HealthBar){var pb=hc.HealthBar.getComponent(cc.ProgressBar);if(pb)pb.progress=hc.hp/hc.maxhp;}
  }
  // 标记对手为蹂躏对象（用于兜底监控）+ 5 次复活计数
  if(oppHc){
    oppHc.__sillyIsOppOf=isP1?1:2;
    if(oppHc.__sillyOppRevivesLeft===undefined)oppHc.__sillyOppRevivesLeft=5;
  }
  // 觉醒方持续 buff（每回合都重新加上）
  try{
    var human=node.getComponent("Human");
    if(human){
      if(human.flyItem)human.flyItem();
      if(human.atkBuffItem)human.atkBuffItem();
      if(human.berserkerItem)human.berserkerItem();
      if(human.sheildItem)human.sheildItem();
    }
  }catch(e){}
  // === reapply 时如果全屏特效不存在，重建 ===
  if(reapply){
    try{
      var cnRe=cc.find("Canvas");
      if(cnRe&&!cnRe.getChildByName("sillyOverlay")){
        var ov2=new cc.Node("sillyOverlay");ov2.parent=cnRe;ov2.setPosition(0,0);ov2.zIndex=996;
        var sz2=cc.winSize;
        ov2.setContentSize(sz2.width*1.5,sz2.height*1.5);
        var sp2=ov2.addComponent(cc.Sprite);
        var tex2=new cc.Texture2D();
        tex2.initWithData(new Uint8Array([255,255,255,255]),cc.Texture2D.PixelFormat.RGBA8888,1,1);
        sp2.spriteFrame=new cc.SpriteFrame(tex2);
        sp2.sizeMode=cc.Sprite.SizeMode.CUSTOM;
        ov2.opacity=80;
        var ovColors2=[cc.Color.RED,cc.Color.YELLOW,cc.Color.GREEN,cc.Color.CYAN,cc.Color.BLUE,cc.Color.MAGENTA,new cc.Color(255,128,0),new cc.Color(255,0,128)];
        var oi2=0;
        var ovInt2=setInterval(function(){
          if(!ov2||!ov2.isValid){clearInterval(ovInt2);return;}
          ov2.color=ovColors2[oi2%ovColors2.length];
          ov2.opacity=40+Math.random()*40;
          oi2++;
        },100);
        console.log("[我装的] reapply: overlay 重建");
      }
    }catch(e){}
  }
  // 视觉特效：每个子 sprite 直接染色 + 光环
  function recolorChild(n,color){
    var sp=n.getComponent(cc.Sprite);
    if(sp)n.color=color;
    n.children.forEach(function(c){recolorChild(c,color);});
  }
  if(!node.__sillyColorTween){
    var rainbowColors=[cc.Color.RED,new cc.Color(255,128,0),cc.Color.YELLOW,cc.Color.GREEN,cc.Color.CYAN,cc.Color.BLUE,cc.Color.MAGENTA,new cc.Color(255,0,128)];
    var rci=0;
    node.__sillyColorTween=setInterval(function(){
      if(!node||!node.isValid){clearInterval(node.__sillyColorTween);return;}
      var c=rainbowColors[rci%rainbowColors.length];
      node.children.forEach(function(ch){recolorChild(ch,c);});
      rci++;
    },80);
  }
  // 巨型光环（在 body 上，半径大、亮）
  var body=node.getChildByName("body");
  if(body){
    var oldA=body.getChildByName("sillyAura");
    if(oldA)oldA.destroy();
    var aura=new cc.Node("sillyAura");aura.parent=body;aura.setPosition(0,0);aura.zIndex=-1;
    var g=aura.addComponent(cc.Graphics);
    var auraColors=[cc.Color.RED,cc.Color.YELLOW,cc.Color.GREEN,cc.Color.CYAN,cc.Color.BLUE,cc.Color.MAGENTA];
    var ci=0;
    var auraInt=setInterval(function(){
      if(!aura||!aura.isValid){clearInterval(auraInt);return;}
      g.clear();
      // 多层环
      for(var li=0;li<3;li++){
        g.lineWidth=12-li*3;
        g.strokeColor=auraColors[(ci+li)%auraColors.length];
        var r=120+li*30+Math.sin(Date.now()/200+li)*15;
        g.circle(0,0,r);
        g.stroke();
      }
      // 内部填充火焰
      g.fillColor=auraColors[ci%auraColors.length];
      g.circle(0,0,30+Math.sin(Date.now()/100)*8);
      g.fill();
      ci++;
    },50);
    cc.tween(aura).repeatForever(cc.tween().by(2,{angle:360})).start();
  }
  // 摄像机持续震动
  try{
    var cam=cc.find("Canvas/Main Camera")||cc.find("Canvas/cam");
    if(cam&&!cam.__sillyShaking){
      cam.__sillyShaking=true;
      cc.tween(cam).repeatForever(cc.tween().by(0.04,{position:cc.v3(10,5,0)}).by(0.04,{position:cc.v3(-10,-5,0)})).start();
    }
  }catch(e){}
  // hook setDamage：觉醒方=超弱跟班，对手=正常
  var hcP=Object.getPrototypeOf(hc);
  if(!hcP.__sillyHooked){
    var oD=hcP.setDamage;
    hcP.setDamage=function(dmg){
      if(!this.node)return;
      var iP1=this.node.name==="StickMan1";
      var awak=(iP1&&window.__sillyAwakenedP1)||(!iP1&&window.__sillyAwakenedP2);
      // 攻击者觉醒：伤害 -90%（觉醒方打人极弱）
      var aP1=!iP1;
      var awakAtk=(aP1&&window.__sillyAwakenedP1)||(!aP1&&window.__sillyAwakenedP2);
      if(awakAtk)dmg=Math.max(1,Math.round(dmg*0.1));
      // 觉醒方自己被攻击：正常受伤（不再无敌）
      return oD.call(this,dmg);
    };
    hcP.__sillyHooked=true;
  }
  // 觉醒方持续监控：移速极慢 + 大招30秒 + 普攻20秒
  if(!window.__sillyHpWatchI){
    window.__sillyHpWatchI=setInterval(function(){
      var cn4=cc.find("Canvas");if(!cn4)return;
      var gm4=cn4.getComponent("Games");if(!gm4)return;
      function nerf(p,joy,p1){
        if(!p||!p.isValid)return;
        var awak=(p1&&window.__sillyAwakenedP1)||(!p1&&window.__sillyAwakenedP2);
        if(!awak)return;
        // 1. 移速极慢：限制水平速度上限 30
        var bd=p.getChildByName("body");
        if(bd){var rb=bd.getComponent(cc.RigidBody);
          if(rb){var v=rb.linearVelocity;
            if(Math.abs(v.x)>30)rb.linearVelocity=cc.v2(30*(v.x>0?1:-1),v.y);
          }
        }
        // 2. 全身关节速度也限制
        p.getComponentsInChildren(cc.RigidBody).forEach(function(rb){
          var v=rb.linearVelocity;
          if(Math.abs(v.x)>50)rb.linearVelocity=cc.v2(50*(v.x>0?1:-1),v.y);
        });
        // 3. 大招冷却 30 秒（默认 10 秒）+ 普攻间隔 20 秒
        if(joy&&joy.isValid){
          var jc=joy.getComponent("JoyStick");
          if(jc){
            // 大招：把 bigSkillNextInterval 设为 30，并让 timer 永远落后
            // 直接每帧把 timer 减回去模拟"3倍冷却"
            if(!jc.bigSkillState&&jc.bigSkillTimer>0){
              jc.bigSkillTimer=Math.max(0,jc.bigSkillTimer-0.033); // 每50ms减0.033，相当于2/3的速度推进，效果约30秒
            }
          }
        }
        // 4. 普攻间隔 20 秒：把武器的 damageInverter 设大
        var ws=cc.find("Canvas").getComponentsInChildren("Weapon");
        ws.forEach(function(w){
          if(w.human&&w.human.parent===p){
            w.damageInverter=20; // 攻击间隔 20 秒
            // 同时清掉 _bsActive 防止 berserkerItem 起作用
            w._bsActive=0;
          }
        });
      }
      nerf(gm4.player,gm4.playerJoy,true);
      nerf(gm4.enemy,gm4.enemyJoy,false);
    },50);
  }
};

