window.diagBtns=function(){
  var cn=cc.find("Canvas");if(!cn)return;
  var cv=cn.getChildByName("ChooseView");if(!cv)return;
  // 递归列出所有节点
  function walk(n,depth){
    var ind="  ".repeat(depth);
    var hasBtn=!!n.getComponent(cc.Button);
    var lbls=n.getComponents(cc.Label);
    var txt=lbls.length>0?lbls[0].string:"";
    console.log(ind+n.name+" x="+Math.round(n.x)+" y="+Math.round(n.y)+(hasBtn?" [BTN]":"")+(txt?" '"+txt+"'":""));
    if(depth<3)n.children.forEach(function(c){walk(c,depth+1);});
  }
  walk(cv,0);
};




/* ════════════════════════════════════════════════════════════════
   新回合状态彻底清理：清除 buff 倒计时 / 暂时性 flag / 视觉残留
   每回合开始时调用一次（在 __lastRoundKey 检测点触发）
   ════════════════════════════════════════════════════════════════ */
;(function(){
window.__resetRoundState=function(gm,hc1,hc2){
  if(window.__pickupHudClear)window.__pickupHudClear();
  try{
    if(!gm)return;
    var players=[gm.player,gm.enemy];
    players.forEach(function(p){
      if(!p||!p.isValid)return;
      if(window.__selectedItemRuntime){
        p.__itemScaleEpoch=(p.__itemScaleEpoch||0)+1;
        window.__selectedItemRuntime.restoreScale(p);
        delete p.__itemScaleBase;
      }
      // 1. 清玩家节点上的临时 flag（道具/被动 buff 字段）
      var nodeFlags=[
        // 道具 buff 倒计时
        "__atkBuffEnd","__berserkEnd","__summonEnd","__flyEnd","__bigEnd",
        "__shrunkEnd","__shrunk","__reflectEnd","__shrunkEnd",
        "__frostUntil","__silenceUntil","__frostlordUntil",        // 被动 buff 一次性应用标记（让它们重新算）
        "__bbApplied","__tbApplied","__thundererApplied",
        "__fortressStill","__cursedTick","__gargoyleTick",
        "__sillyAwakenedAura","__sillyParticles",
        // 第六批新被动
        "__bulwarkStill","__bulwarkShield","__compoundStart","__compoundStacks",
        // 道具拾取就绪
        "__bloodthirstReady","__hunterReady","__counterReady",
        "__feathered",
        // 视觉残留（光环、护盾等）
        "__pGCApplied"
      ];
      nodeFlags.forEach(function(k){try{delete p[k];}catch(_){}});
      // 2. 清 HumanController 上的 buff flag
      var hc=p.getComponent("HumanController");
      if(hc){
        hc.__reviveEpoch=(hc.__reviveEpoch||0)+1;
        var hcFlags=[
          "__atkBuffEnd","__berserkEnd","__summonEnd","__flyEnd","__bigEnd",
          "__reflectEnd","__reflectActive","__reflectOnce",
          "__bloodthirstReady","__hunterReady","__counterReady","__counterStrike",
          "__triplecast","__phoenixInvuln","__phoenixUsed","__phoenixLocked",
          "__totemReady","__totemUsed","__totemInvuln",
          "__inBigSkill","__rageTotal","__lifelineUsed","__silenced",
          "__endlessRevInvuln",
          "__echoQueue","__bulwarkShield","__disarmEnd","__giantLayerApplied"
        ];
        hcFlags.forEach(function(k){try{delete hc[k];}catch(_){}});
        // 重要：保留 hp/maxhp 不动（原版 reset 会处理），但确保 isInvincible 清掉
        if(typeof hc.isInvincible!=="undefined")hc.isInvincible=false;
      }
      // 3. 清子节点上的视觉特效残留
      var body=p.getChildByName("body");
      if(body){
        ["totemHalo","reflectAura","reflect5sAura","frostAura","goldenDome",
         "phoenixAura","sillyAura","sillyParticles","bloodAura"].forEach(function(name){
          var ch=body.getChildByName(name);
          if(ch&&ch.isValid)ch.destroy();
        });
      }
      // 玩家根节点下的特效
      ["Centers"].forEach(function(){});
      // 体型残留：如果上一回合用了巨化/缩小但没还原，重置 scale
      // 安全做法：只在 scale 异常（>1.4 或 <0.7）时强制还原
      try{
        if(Math.abs(p.scaleX)>1.4||Math.abs(p.scaleX)<0.7){
          var origAbs=Math.abs(p.scaleX);
          var sign=p.scaleX>0?1:-1;
          // 还原所有 joint anchor
          p.getComponentsInChildren(cc.Joint).forEach(function(j){
            if(j.anchor){j.anchor=cc.v2(j.anchor.x/origAbs,j.anchor.y/origAbs);j.apply&&j.apply();}
            if(j.connectedAnchor){j.connectedAnchor=cc.v2(j.connectedAnchor.x/origAbs,j.connectedAnchor.y/origAbs);j.apply&&j.apply();}
          });
          p.scaleX=sign;p.scaleY=1;
        }
      }catch(_){}
      // 重置 RigidBody.gravityScale 到默认（清除漂浮羽毛 / 重力锚残留）
      try{
        p.getComponentsInChildren(cc.RigidBody).forEach(function(rb){
          // 只在异常时重置：>3 (重力锚) 或 <0.3 (漂浮羽毛/飞行)
          // 默认值通常 1，飞行物 0
          if(rb.gravityScale>3||(rb.gravityScale>0&&rb.gravityScale<0.3)){
            rb.gravityScale=1;
          }
        });
      }catch(_){}
      // 节点透明度还原
      if(p.opacity<200)p.opacity=255;
    });
    [gm.playerJoy,gm.enemyJoy].forEach(function(joy){
      if(!joy||!joy.isValid)return;
      var jc=joy.getComponent("JoyStick");
      if(jc)jc.__phoenixLocked=false;
    });
    // 4. 全局 flag
    var globalFlags=[
      "__timeStopActive","__timeStopOwner","__timeStopEnd",
      "__lastSoulSwap","__shrinkI"
    ];
    globalFlags.forEach(function(k){
      try{
        if(k==="__shrinkI"&&window[k]){clearInterval(window[k]);}
        delete window[k];
      }catch(_){}
    });
    // 5. 清屏幕上残留的全局节点（time stop overlay / 各种 banner）
    var canvas=cc.find("Canvas");
    if(canvas){
      ["timeStopOverlay","tsLbl","triplecast","lifeline","clericHeal",
       "hookLine","sillyAwakenLabel","sillyDeathBanner","merchant"
      ].forEach(function(name){
        var n=canvas.getChildByName(name);
        if(n&&n.isValid)n.destroy();
      });
    }
    // 6. 重置 endless flag（如果在 endless 模式中）
    // (endless 模式不用这里，这是普通 2P 回合)
    // 7. 重置 game-level flag
    if(gm){
      gm.__pGCApplied=false;
      gm.__roundStart=Date.now();
    }
    console.log("[ROUND] 状态已重置");
    // 玩家血量翻倍（50 → 100）
    players.forEach(function(p){
      if(!p||!p.isValid)return;
      var hc=p.getComponent("HumanController");
      if(hc){
        hc.maxhp=100;
        hc.hp=100;
        if(hc.HealthBar){var pb=hc.HealthBar.getComponent(cc.ProgressBar);if(pb)pb.progress=1;}
      }
    });
  }catch(e){console.log("[ROUND] reset err:",e&&e.message);}
};
})();


/* ════════════════════════════════════════════════════════════════
   江城圆体字体加载 + 全局 Label 字体应用 + 中文换行 helper
   ════════════════════════════════════════════════════════════════ */
;(function(){
// 1. 通过 CSS @font-face 加载 ttf —— 让 cc.Label.fontFamily 可识别
window.__JC_FONT="JCRound";
(function injectFontFace(){
  if(document.getElementById("__jc_font_style"))return;
  var style=document.createElement("style");
  style.id="__jc_font_style";
  style.textContent='@font-face{font-family:"JCRound";src:url("assets/JCRound.ttf") format("truetype");font-display:block;}';
  document.head.appendChild(style);
  // 强制预载（让浏览器立即下载）
  var img=document.createElement("div");
  img.style.cssText='position:absolute;left:-9999px;font-family:"JCRound";';
  img.textContent="测试";
  document.body.appendChild(img);
  console.log("[FONT] 江城圆体已注入");
})();

// 2. 中文换行 helper：每 N 个字符插入 \n
window.__zhWrap=function(text,maxCharsPerLine){
  if(!text)return "";
  if(typeof text!=="string")text=String(text);
  if(text.length<=maxCharsPerLine)return text;
  var lines=[];
  // 按 maxCharsPerLine 切分（中文每字算 1）
  for(var i=0;i<text.length;i+=maxCharsPerLine){
    lines.push(text.slice(i,i+maxCharsPerLine));
  }
  return lines.join("\n");
};

// 3. 给所有 Label 应用江城圆体字体（通过 fontFamily + useSystemFont）
//    关键：必须等 @font-face 真正加载完成（document.fonts.ready）后再应用，
//    否则 Label 会用 fallback 渲染一次且被标记 applied，再也不会换成江城圆体。
(function(){
  window.__jcFontReady=false;
  // 强制加载字体并等就绪
  function whenFontReady(cb){
    try{
      if(document.fonts&&document.fonts.load){
        document.fonts.load('24px "JCRound"',"测试中文ABC").then(function(){
          if(document.fonts.ready){document.fonts.ready.then(cb);}else{cb();}
        }).catch(function(){cb();});
      }else{
        // 老浏览器无 FontFaceSet：延迟 1.5s 兜底
        setTimeout(cb,1500);
      }
    }catch(e){setTimeout(cb,1500);}
  }
  whenFontReady(function(){
    window.__jcFontReady=true;
    console.log("[FONT] 江城圆体加载完成，开始应用到 Label");
  });

  // 给单个 Label 应用江城圆体 + 强制重渲染
  function applyJC(lbl){
    if(!lbl||!lbl.isValid)return;
    try{
      if(typeof lbl.useSystemFont!=="undefined")lbl.useSystemFont=true;
      if(typeof lbl.fontFamily!=="undefined"){
        var cur=lbl.fontFamily||"";
        if(cur.indexOf("JCRound")<0)lbl.fontFamily="JCRound, "+(cur||"sans-serif");
      }
      // 强制重渲染：cocos 2.4 改 string 会触发 _updateRenderData
      var s=lbl.string;
      lbl.string="";
      lbl.string=s;
      if(typeof lbl._forceUpdateRenderData==="function")lbl._forceUpdateRenderData(true);
      lbl.__jcApplied=true;
    }catch(e){}
  }
  window.__applyJCFont=applyJC;

  var tries=0;
  var ti=setInterval(function(){
    tries++;
    if(tries>60){clearInterval(ti);return;}
    if(!cc||!cc.Label||!cc.Label.prototype){return;}
    clearInterval(ti);
    // combat-perf-r2：Label 生命周期由后置注册表接管；字体就绪时只做一次既有标签扫描。
    console.log("[FONT] Label lifecycle hook deferred to combat-perf-r2");
  },300);
})();
})();



// combat-perf-r2：Weapon 防空改为实例/工厂登记，见后置 runtime.

// === TranslateLbl 防崩保护 ===
// 新版 mainScenes 34a7c 引入了一些 locKey（比如 ChooseView 上的 soccer 标签）但 locs 表里没匹配
// 导致 TranslateLbl.onLoad 里 queryByID 返回 undefined，再读 .en 就崩溃
// 通过 hook localConfig.instance.queryByID 在表里没命中时返回 {en: locKey, zh: locKey} 占位
;(function(){
  var hooked=false;
  var hi=setInterval(function(){
    if(hooked){clearInterval(hi);return;}
    try{
      var lc=window.__require&&window.__require("localConfig");
      if(!lc||!lc.localConfig||!lc.localConfig.instance)return;
      var inst=lc.localConfig.instance;
      if(inst.__locPatched)return;
      var orig=inst.queryByID.bind(inst);
      inst.queryByID=function(table,key){
        try{
          var r=orig(table,key);
          if((r==null||r==undefined)&&table==="locs"){
            // 仅 locs 表未命中时返回语言占位，其他表（leaders 等）保持 undefined
            return {en:key||"",zh:key||"",fr:key||"",de:key||"",es:key||"",pt:key||"",ru:key||"",ja:key||"",ko:key||""};
          }
          return r;
        }catch(e){
          if(table==="locs")return {en:key||"",zh:key||""};
          return null;
        }
      };
      inst.__locPatched=true;
      hooked=true;
      console.log("[LOC] TranslateLbl 防崩保护已安装");
    }catch(e){}
  },300);
})();

