  g.circle(0,0,31);g.fill();g.stroke();g.moveTo(-43,0);g.lineTo(43,0);g.moveTo(0,-43);g.lineTo(0,43);g.stroke();
  var l=label(mark,"countdown","回锚 3.0",52,21,new cc.Color(185,250,255));
  var scene=cc.director.getScene();
